10	
11	#include "ascir/Target/Asc/External/Scf.h"
12	
13	using namespace mlir;
14	
15	LogicalResult mlir::emitBlock(CodeEmitter& codeEmitter, Block& block)
16	{
17	    for (auto& op : block) {
18	        if (isa<scf::YieldOp>(op) && op.getNumOperands() == 0) {
19	            continue;
20	        }
21	        FAIL_OR(emitOperation(codeEmitter, op, needsSemicolon(op)));
22	    }
23	    return success();
24	}
25	
26	LogicalResult mlir::printOperation(CodeEmitter& codeEmitter, scf::ForOp forOp)
27	{
28	    raw_indented_ostream& os = codeEmitter.ostream();
29	
30	    OperandRange operands = forOp.getInitArgs();
31	    Block::BlockArgListType iterArgs = forOp.getRegionIterArgs();
32	    Operation::result_range results = forOp.getResults();
33	
34	    for (OpResult result : results) {
35	        if (failed(codeEmitter.emitVariableDeclaration(result, /*trailingSemicolon=*/true))) {
36	            return failure();
37	        }
38	    }
39	
40	    for (auto pair : llvm::zip(iterArgs, operands)) {
41	        if (failed(codeEmitter.emitType(forOp.getLoc(), std::get<0>(pair).getType()))) {
42	            return failure();
43	        }
44	        os << " " << codeEmitter.getOrCreateName(std::get<0>(pair)) << " = ";
45	        os << codeEmitter.getOrCreateName(std::get<1>(pair)) << ";";
46	        os << "\n";
47	    }
48	
49	    os << "for (";
50	    FAIL_OR(codeEmitter.emitType(forOp.getLoc(), forOp.getInductionVar().getType()));
51	    os << " " << codeEmitter.getOrCreateName(forOp.getInductionVar());
52	    os << " = " << codeEmitter.getOrCreateName(forOp.getLowerBound());
53	    os << "; " << codeEmitter.getOrCreateName(forOp.getInductionVar());
54	    os << " < " << codeEmitter.getOrCreateName(forOp.getUpperBound());
55	    os << "; " << codeEmitter.getOrCreateName(forOp.getInductionVar());
56	    os << " += " << codeEmitter.getOrCreateName(forOp.getStep()) << ") {\n";
57	    os.indent();
58	
59	    Region& forRegion = forOp.getRegion();
60	    auto regionOps = forRegion.getOps();
61	
62	    // We skip the trailing yield op because this updates the result variables
63	    // of the for op in the generated code. Instead we update the iterArgs at
64	    // the end of a loop iteration and set the result variables after the for
65	    // loop.
66	    for (auto it = regionOps.begin(); std::next(it) != regionOps.end(); ++it) {
67	        Operation& op = *it;
68	        if (failed(emitOperation(codeEmitter, op, needsSemicolon(op)))) {
69	            return failure();
70	        }
71	    }
72	
73	    auto yieldOp = cast<scf::YieldOp>(forOp.getBody()->getTerminator());
74	    // Copy yield operands into iterArgs at the end of a loop iteration.
75	    for (auto [iterArg, operand] : llvm::zip(iterArgs, yieldOp.getResults())) {
76	        os << codeEmitter.getOrCreateName(iterArg) << " = " << codeEmitter.getOrCreateName(operand) << ";\n";
77	    }
78	
79	    os.unindent() << "}";
80	
81	    if (!results.empty()) {
82	        os << "\n";
83	    }
84	    // Copy iterArgs into results after the for loop.
85	    llvm::interleave(
86	        llvm::zip(results, iterArgs),
87	        [&](auto pair) {
88	            auto& [result, iterArg] = pair;
89	            os << codeEmitter.getOrCreateName(result) << " = " << codeEmitter.getOrCreateName(iterArg) << ";";
90	        },
91	        [&] { os << "\n"; });
92	    return success();
93	}
94	
95	LogicalResult mlir::printOperation(CodeEmitter& codeEmitter, scf::IfOp ifOp)
96	{
97	    auto& os = codeEmitter.ostream();
98	
99	    for (OpResult result : ifOp.getResults()) {
100	        if (failed(codeEmitter.emitVariableDeclaration(
101	                result,
102	                /*trailingSemicolon=*/true))) {
103	            return failure();
104	        }
105	    }
106	    os << "if (";
107	    if (failed(codeEmitter.emitOperands(*ifOp.getOperation()))) {
108	        return failure();
109	    }
110	    os << ") {\n";
111	    os.indent();
112	    FAIL_OR(emitBlock(codeEmitter, *ifOp.thenBlock()));
