#include "ascir/Target/Asc/External/MemRef.h"

using namespace mlir;

LogicalResult mlir::printOperation(CodeEmitter& emitter, memref::AllocaOp op)
{
    auto mrType = op.getMemref().getType();
    FAIL_OR(emitter.emitType(op.getLoc(), mrType.getElementType(), op->hasAttr(ascendc::attr::emitAsUnsigned)));
    auto& os = emitter.ostream();
    os << " " << emitter.getOrCreateName(op.getResult());
    for (int64_t dim : mrType.getShape()) {
        os << "[" << dim << "]";
    }
    return success();
}

LogicalResult mlir::printOperation(CodeEmitter& emitter, memref::LoadOp op)
{
    if (failed(emitter.emitAssignPrefix(*op))) {
        return failure();
    }
    auto& os = emitter.ostream();
    os << emitter.getOrCreateName(op.getMemref());
    for (Value index : op.getIndices()) {
        os << "[" << emitter.getOrCreateName(index) << "]";
    }
    return success();
}

LogicalResult mlir::printOperation(CodeEmitter& emitter, memref::StoreOp op)
{
    auto& os = emitter.ostream();
    os << emitter.getOrCreateName(op.getMemref());
    for (Value index : op.getIndices()) {
        os << "[" << emitter.getOrCreateName(index) << "]";
    }
    os << " = " << emitter.getOrCreateName(op.getValueToStore());
    return success();
}

LogicalResult mlir::printOperation(CodeEmitter& emitter, memref::CastOp op)
{
    FAIL_OR(emitter.emitVariableDeclaration(op->getResult(0), false));
    auto& os = emitter.ostream();
    os << " = reinterpret_cast<";
    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
    os << ">(" << emitter.getOrCreateName(op.getSource()) << ")";
    return success();
}

class GlobalAddress(IRValue):

    def __init__(self, handle: IRHandle, dtype: Optional[DataType] = None):
        """This contructor should not be called by user"""
        self.handle = handle
        self.dtype = dtype

    def __repr__(self) -> str:
        return f"GlobalAddress(dtype={self.dtype}, handle=...)"

    @require_jit
    def __add__(self, offset: "RuntimeInt") -> GlobalAddress:
        offset = materialize_ir_value(offset, KT.int_)
        builder = global_builder.get_ir_builder()
        offset_index = builder.create_arith_IndexCastOp(offset.to_ir(), builder.get_index_type())
        handle = builder.create_emitasc_PtrOffsetOp(self.to_ir(), offset_index)
        return GlobalAddress(handle, self.dtype)

    @classmethod
    def from_ir(cls, handle: IRHandle) -> Self:
        return GlobalAddress(handle, DataType.from_ir(ir.get_element_type(handle.get_type())))

    def to_ir(self) -> IRHandle:
        return self.handle


class PlainValue(IRValue):

    def __init__(self, handle: IRHandle, dtype: Optional[DataType] = None):
        """This contructor should not be called by user"""

@require_jit
def __initjit__(self, **fields) -> None:
    builder = global_builder.get_ir_builder()
    self.handle = builder.create_asc_ConstructOp(self.get_ir_type(), [])
    for name, value in fields.items():
        self.__setattrjit__(name, value)

@require_jit
def __getattrjit__(self, name: str) -> PlainValue:
    field = self.get_field(name)
    ir_name = field.ir_name(name)
    handle = global_builder.get_ir_builder().create_emitasc_MemberOp(self.to_ir(), ir_name, field.ir_type())
    return field.from_ir(handle)

@require_jit
def __setattrjit__(self, name: str, value: RuntimeNumeric) -> None:
    field = self.get_field(name)
    ir_name = field.ir_name(name)
    ir_value = field.to_ir(value)
    ir_type = field.ir_type(setter=True)
    builder = global_builder.get_ir_builder()
    if ir_type != ir_value.get_type():
        ir_value = builder.create_asc_ConstructOp(ir_type, [ir_value])
    builder.create_emitasc_SetMemberOp(self.to_ir(), ir_name, ir_value)

@classmethod
def from_ir(cls, handle: IRHandle) -> Self:
    return cls(handle=handle)

@classmethod
def get_field(cls, name: str) -> BaseField:
    field = cls.struct_fields.get(name)
    if field is None:
        raise RuntimeError(f"{cls.__name__} does not have a field '{name}'")
    return field

@classmethod
def get_ir_type(cls) -> ir.Type:
    types = []
    names = []
    for name, field in cls.struct_fields.items():
        names.append(name)
        types.append(field.ir_type())
    return global_builder.get_ir_builder().get_emitasc_PyStructType(cls.__name__, types, names)

def to_ir(self) -> IRHandle:
    return self.handle

def addressof(self) -> int:
    return int(ctypes.addressof(self.ctypes_struct))

def pack(self) -> bytes:
    if not isinstance(self.ctypes_struct, ctypes.Structure):
        raise RuntimeError(f"ctypes.Structure instance must be generated in {self.__class__.__name__}")
    return ctypes.string_at(ctypes.addressof(self.ctypes_struct), ctypes.sizeof(self.ctypes_struct))

def create_local(self) -> Self:
    builder = global_builder.get_ir_builder()
    handle = builder.create_emitasc_CopyStructOp(self.to_ir())
    return self.from_ir(handle)

